118	            || this.clinicService.existsOwnerWithTelephone(owner.getTelephone())
119	            || this.clinicService.existsOwnerWithEmail(owner.getEmail())) {
120	            return new ResponseEntity<>(HttpStatus.CONFLICT);
121	        }
122	        long namesakeCount = this.clinicService.findAllOwners().stream()
123	            .filter(existing -> existing.getLastName() != null
124	                && existing.getLastName().equals(owner.getLastName()))
125	            .count();
126	        owner.setNamesakeCount((int) namesakeCount);
127	        int ownersBefore = this.clinicService.findAllOwners().size();
128	        owner.setMembershipNumber(ownersBefore + 1);
129	        owner.setMembershipTier(ownersBefore < 100 ? "FOUNDING" : "STANDARD");
130	        owner.setCity(resolveCityName(owner.getCity()));
131	        long ownersInCity = this.clinicService.findAllOwners().stream()
132	            .filter(existing -> existing.getCity() != null
133	                && existing.getCity().equalsIgnoreCase(owner.getCity()))
134	            .count();
135	        if (ownersInCity >= 8) {
136	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
137	        }
138	        owner.setCustomerCode(String.format("%s-%04d",
139	            owner.getCity().toUpperCase(Locale.ROOT), ownersInCity + 1));
140	        boolean sharesHousehold = this.clinicService.findAllOwners().stream()
141	            .anyMatch(existing -> existing.getAddress() != null
142	                && existing.getAddress().equals(owner.getAddress())
143	                && existing.getCity() != null
144	                && existing.getCity().equalsIgnoreCase(owner.getCity()));
145	        owner.setSharesHousehold(sharesHousehold);
