154	    /**
155	     * Resolves the city name to store for a newly created owner. If another owner already
156	     * lives in the same city (compared case-insensitively), that owner's exact spelling of
157	     * the city is reused so a city keeps a single canonical spelling. Otherwise the supplied
158	     * city is title-cased (each word capitalised, remaining letters lower-cased).
159	     *
160	     * @param city the raw city supplied for the new owner (may be {@code null})
161	     * @return the city name to store, or {@code null} if {@code city} is {@code null}
162	     */
163	    private String resolveCityName(String city) {
164	        if (city == null) {
165	            return null;
166	        }
167	        return this.clinicService.findAllOwners().stream()
168	            .map(Owner::getCity)
169	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
