174	    /**
175	     * Title-cases a city name: the first letter of every whitespace-separated word is
176	     * upper-cased and the remaining letters are lower-cased, e.g. {@code "new  YORK"}
177	     * becomes {@code "New  York"}. Whitespace is preserved as-is.
178	     *
179	     * @param city the city name to title-case
180	     * @return the title-cased city name
181	     */
182	    private static String toTitleCase(String city) {
183	        StringBuilder result = new StringBuilder(city.length());
184	        boolean startOfWord = true;
185	        for (int i = 0; i < city.length(); i++) {
186	            char c = city.charAt(i);
187	            if (Character.isWhitespace(c)) {
188	                startOfWord = true;
189	                result.append(c);
190	            } else {
191	                result.append(startOfWord
192	                    ? Character.toTitleCase(c)
193	                    : Character.toLowerCase(c));
194	                startOfWord = false;
195	            }
196	        }
197	        return result.toString();
