200	    /**
201	     * Determines whether the supplied city is the single most common city among the owners that
202	     * already exist. Cities are compared case-insensitively. A city qualifies only when strictly
203	     * more existing owners live there than in any other city; if the city is absent, tied for the
204	     * lead, or there are no existing owners at all, it is not the single most common city.
205	     *
206	     * @param city the (already canonicalised) city of the owner being created (may be {@code null})
207	     * @return {@code true} if {@code city} is uniquely the most common existing city
208	     */
209	    private boolean isMostCommonCity(String city) {
210	        if (city == null) {
211	            return false;
212	        }
213	        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
214	            .map(Owner::getCity)
215	            .filter(existing -> existing != null)
216	            .collect(Collectors.groupingBy(c -> c.toLowerCase(Locale.ROOT), Collectors.counting()));
217	        long max = countsByCity.values().stream().mapToLong(Long::longValue).max().orElse(0L);
218	        if (max == 0L) {
219	            return false;
220	        }
221	        long numberOfCitiesWithMax = countsByCity.values().stream()
222	            .filter(count -> count == max)
223	            .count();
224	        if (numberOfCitiesWithMax != 1L) {
225	            return false;
226	        }
227	        Long cityCount = countsByCity.get(city.toLowerCase(Locale.ROOT));
228	        return cityCount != null && cityCount == max;
229	    }
