        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
        HttpHeaders headers = new HttpHeaders();
        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
        if (owner.getRegistrationDate() == null) {
            owner.setRegistrationDate(LocalDate.now());
        }
        long ownersRegisteredToday = this.clinicService.findAllOwners().stream()
            .filter(existing -> LocalDate.now().equals(existing.getRegistrationDate()))
            .count();
        if (ownersRegisteredToday >= 20) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
        if (this.clinicService.existsIdenticalOwner(owner)
            || this.clinicService.existsOwnerWithTelephone(owner.getTelephone())
            || this.clinicService.existsOwnerWithEmail(owner.getEmail())) {
            return new ResponseEntity<>(HttpStatus.CONFLICT);
        }
        long namesakeCount = this.clinicService.findAllOwners().stream()
            .filter(existing -> existing.getLastName() != null
                && existing.getLastName().equals(owner.getLastName()))
            .count();
        owner.setNamesakeCount((int) namesakeCount);
        int ownersBefore = this.clinicService.findAllOwners().size();
        owner.setMembershipNumber(ownersBefore + 1);
        owner.setMembershipTier(ownersBefore < 100 ? "FOUNDING" : "STANDARD");
        owner.setCity(resolveCityName(owner.getCity()));
        long ownersInCity = this.clinicService.findAllOwners().stream()
            .filter(existing -> existing.getCity() != null
                && existing.getCity().equalsIgnoreCase(owner.getCity()))
            .count();
        if (ownersInCity >= 8) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
        owner.setCustomerCode(String.format("%s-%04d",
            owner.getCity().toUpperCase(Locale.ROOT), ownersInCity + 1));
        boolean sharesHousehold = this.clinicService.findAllOwners().stream()
            .anyMatch(existing -> existing.getAddress() != null
                && existing.getAddress().equals(owner.getAddress())
                && existing.getCity() != null
                && existing.getCity().equalsIgnoreCase(owner.getCity()));
        owner.setSharesHousehold(sharesHousehold);
        owner.setLocality(isMostCommonCity(owner.getCity()) ? "local" : "remote");
        this.clinicService.saveOwner(owner);
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }

    /**
     * Resolves the city name to store for a newly created owner. If another owner already
     * lives in the same city (compared case-insensitively), that owner's exact spelling of
     * the city is reused so a city keeps a single canonical spelling. Otherwise the supplied
     * city is title-cased (each word capitalised, remaining letters lower-cased).
     *
     * @param city the raw city supplied for the new owner (may be {@code null})
     * @return the city name to store, or {@code null} if {@code city} is {@code null}
     */
    private String resolveCityName(String city) {
        if (city == null) {
            return null;
        }
        return this.clinicService.findAllOwners().stream()
            .map(Owner::getCity)
            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
            .findFirst()
            .orElseGet(() -> toTitleCase(city));
    }

    /**
     * Title-cases a city name: the first letter of every whitespace-separated word is
     * upper-cased and the remaining letters are lower-cased, e.g. {@code "new  YORK"}
     * becomes {@code "New  York"}. Whitespace is preserved as-is.
     *
     * @param city the city name to title-case
     * @return the title-cased city name
     */
    private static String toTitleCase(String city) {
        StringBuilder result = new StringBuilder(city.length());
        boolean startOfWord = true;
        for (int i = 0; i < city.length(); i++) {
            char c = city.charAt(i);
            if (Character.isWhitespace(c)) {
                startOfWord = true;
                result.append(c);
            } else {
                result.append(startOfWord
                    ? Character.toTitleCase(c)
                    : Character.toLowerCase(c));
                startOfWord = false;
            }
        }
        return result.toString();
    }

    /**
     * Determines whether the supplied city is the single most common city among the owners that
     * already exist. Cities are compared case-insensitively. A city qualifies only when strictly
     * more existing owners live there than in any other city; if the city is absent, tied for the
     * lead, or there are no existing owners at all, it is not the single most common city.
     *
     * @param city the (already canonicalised) city of the owner being created (may be {@code null})
     * @return {@code true} if {@code city} is uniquely the most common existing city
     */
    private boolean isMostCommonCity(String city) {
        if (city == null) {
            return false;
        }
        Map<String, Long> countsByCity = this.clinicService.findAllOwners().stream()
            .map(Owner::getCity)
            .filter(existing -> existing != null)
            .collect(Collectors.groupingBy(c -> c.toLowerCase(Locale.ROOT), Collectors.counting()));
        long max = countsByCity.values().stream().mapToLong(Long::longValue).max().orElse(0L);
        if (max == 0L) {
            return false;
        }
        long numberOfCitiesWithMax = countsByCity.values().stream()
            .filter(count -> count == max)
            .count();
        if (numberOfCitiesWithMax != 1L) {
            return false;
        }
        Long cityCount = countsByCity.get(city.toLowerCase(Locale.ROOT));
        return cityCount != null && cityCount == max;
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        currentOwner.setAddress(ownerFieldsDto.getAddress());
        currentOwner.setCity(ownerFieldsDto.getCity());
        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
        currentOwner.setLastName(ownerFieldsDto.getLastName());
        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
        this.clinicService.saveOwner(currentOwner);
        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Transactional
    @Override
    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        this.clinicService.deleteOwner(owner);
        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
        Owner owner = this.clinicService.findOwnerById(ownerId);
        if (owner == null) {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
        HttpHeaders headers = new HttpHeaders();
        Pet pet = petMapper.toPet(petFieldsDto);
        owner.setId(ownerId);
        pet.setOwner(owner);
        pet.getType().setName(null);
        this.clinicService.savePet(pet);
        PetDto petDto = petMapper.toPetDto(pet);
        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
            .buildAndExpand(pet.getId()).toUri());
        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
    }

    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
    @Override
    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
        if (currentOwner != null) {
            Pet currentPet = this.clinicService.findPetById(petId);
            if (currentPet != null) {
                currentPet.setBirthDate(petFieldsDto.getBirthDate());
                currentPet.setName(petFieldsDto.getName());
                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
                this.clinicService.savePet(currentPet);
                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
            }
        }
        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
    }

